        "h": "主目标与撤离的关系",
        "p": "主目标决定任务是否成功，撤离更多决定你能否稳定拿到最后的收益。很多新手会把“活着撤离”误解成任务成功的唯一标准，但实际上只要主目标完成，任务逻辑就已经成立。真正需要谨慎的是高压撤离阶段，因为这时最容易因为贪输出、站位乱或者路线断掉而翻车。"
