    "body": [
      "这篇文章的目标不是“告诉你一个名字”，而是把 Helldivers 2 虫族撤离攻略 15 拆成能直接上手的打法。Helldivers 2 的攻略价值，往往不在于单个数值，而在于你能否把地图、敌人和队伍组合成一套可执行方案。",
      "核心结论：撤离阶段要提前清路线，不要被刷新点截断。 在大多数任务里都成立。你可以把它理解成一条实战准则——先稳住局面，再追求效率；先处理风险，再追求击杀。",
      "在实际对局中，最常见的失败点通常集中在三个位置：接敌第一波、目标点清场、撤离阶段。假如你在这三个阶段都能保持队形不乱，通关率会明显上升。",
      "如果你是单人或双排，建议把注意力更多放在路线和撤离；如果你是四排，则应该把分工和火力覆盖放在第一位。不同人数下的最优策略并不一样，强行套用同一套配法，往往会让团队效率下降。",
      "下面给出可直接执行的细分建议：",
      "虫族场景下，撤离是决定胜负的第一要素。",
      "根据常见高难实战经验，Helldivers 2 虫族撤离攻略 15 最容易出问题的不是输出，而是节奏、站位和撤离。",
      "建议把前 3 分钟当作建立优势的窗口期，把最后 30 秒当作保命窗口期。",
      "实战里还有一个非常重要的判断标准：当你开始频繁需要“临时补救”时，说明不是枪不够强，而是整体节奏已经乱了。此时最有效的做法通常不是继续硬打，而是退一步重整站位，再重新推进。",
      "如果你要把这篇攻略变成稳定收藏页，建议配合你的当前版本、难度等级和阵营来微调。原则上，只要遵守“先控场、后输出；先站稳、后推进；先保命、再刷分”，这类打法都能长期使用。"
    ],
