    "coverImage": "https://placehold.co/1200x675/0f172a/f2c94c?text=Strategy+Guide",
    "coverAlt": "战略配备指南封面",
    "imageNote": "原创重写内容：基于公开攻略方向整理的实战版战略配备指南。",
    "sourceNotes": [
      "参考公开攻略中关于支持武器、轨道打击、鹰式打击、哨兵、背包的选择思路。",
      "重点保留“场景优先于纸面数值”的核心方法，而不是照搬原文表格。"
    ],
    "sections": [
      {
        "h": "为什么战略配备比单把枪更重要",
        "p": "Helldivers 2 的真正强度往往来自整套战略配备的协同，而不是某一把武器本身。一次任务里你最多只能携带 4 个战略配备，这意味着每个槽位都必须同时承担清杂、对甲、控场、救场中的至少一个职责。"
      },
      {
        "h": "支持武器该怎么选",
        "p": "支持武器的本质是“把一个槽位换成一件能持续改变战局的手持工具”。无后坐力步枪适合稳定点杀重甲，自动炮兼顾对甲与清场，夸萨炮更适合单人持续作战，而突击队型火箭则偏向一次解决多个关键目标。选择时不要只看爆发，还要看补给压力、充能节奏和队伍分工。"
      },
      {
        "h": "轨道与鹰式怎么分工",
        "p": "轨道类更适合精确点杀和长冷却高价值目标，鹰式则更适合高频使用和快速节奏。打大型目标时，500kg 炸弹和轨道炮类更像“关键回合牌”；而空袭、集束、精确打击则更像“常驻工具”。如果你队伍缺少持续控场能力，先保证能频繁呼叫的选项，而不是盲目堆最贵的爆发。"
      },
      {
        "h": "哨兵和地雷的正确打开方式",
        "p": "哨兵与地雷最怕的不是敌人，而是队友误入和投放位置错误。哨兵要尽量放在高点或侧翼，让火力覆盖敌人的推进路线而不是队伍站位；地雷则要用于逼迫敌人改路线，尤其适合固定防守、撤离口和狭窄通道。任何情况下都不要把哨兵和地雷当成无脑输出，它们的价值在“创造战场形状”。"
      },
      {
        "h": "背包位如何决定打法",
        "p": "护盾背包提高容错，补给背包提高持续战斗能力，跳跃背包则换来机动和脱战能力。护盾背包适合被远程威胁压制的地图；补给背包适合弹药消耗很大的队伍；跳跃背包则更适合虫族图和高低差地形。一个好的背包选择，往往能直接改变整局的推进节奏。"
      },
      {
        "h": "实战结论",
        "p": "如果你想要一套不容易翻车的通用配置，建议把思路固定为：一个稳定对甲，一个稳定清杂，一个保命或机动，一个高价值爆发。这样无论面对虫族、机器人还是撤离任务，你都不会陷入“全队都有火力但没有解法”的尴尬局面。"
      }
    ],
