    "title": "Major Orders 指南：赢得银河战争的胜利",
    "category": "任务",
    "tags": [
      "Major Orders",
      "银河战争",
      "社区协作"
    ],
    "updatedAt": "2026-05-09",
    "summary": "解释 Major Orders 的意义、为什么常失败，以及普通玩家如何有效贡献。",
    "stats": {
      "difficulty": "进阶",
      "solo": 66,
      "coop": 95,
      "recommendation": "适合组队阅读"
    },
    "coverImage": "https://placehold.co/1200x675/0f172a/58d7ff?text=Major+Orders",
    "coverAlt": "Major Orders 指南封面",
    "imageNote": "原创重写内容：围绕社区目标、优先星球和协作节奏进行整理。",
    "sourceNotes": [
      "参考公开攻略中关于 Major Orders、补给线、优先星球和阵营匹配的思路。",
      "避免照搬原文表述，改写为适合中文玩家理解的执行版指南。"
    ],
    "sections": [
      {
        "h": "Major Orders 是什么",
        "p": "Major Orders 可以理解为整个社区共同完成的限时战役目标。它并不是单局任务，而是跨服务器、跨时段的共享进度条。你今天打的每一场，最后都可能汇聚成一次解放、一场防御，或者一次剧情推进。"
      },
      {
        "h": "为什么很多人总是跟错方向",
        "p": "大多数失败不是因为任务太难，而是因为玩家没有统一信息：不知道优先去哪颗星球，不知道补给线怎么连，也不知道防守和解放的区别。结果大家各打各的，力量被分散到无关紧要的地图上。"
      },
      {
        "h": "玩家能做的最有效事情",
        "p": "打开银河战争地图后，先看当前 Major Orders 要求什么，再看目标是否被补给线连接。若是解放型目标，就直接去目标星球；若是防守型目标，就集中在相关战区刷任务。不要因为某颗星球看起来“顺路”就偏离主线。"
      },
      {
        "h": "配装为什么要跟着战区走",
        "p": "不同战区会强迫你面对不同地形和敌人。虫族战区更偏向近距离、高机动、控场和群体压制；机器人战区更需要稳定对甲和远程打击。Major Orders 期间最容易犯的错，就是带着一套固定配装打所有战线。"
      },
      {
        "h": "小队协作比个人效率更关键",
        "p": "任务贡献是共享的，所以救人、补给、集合和推进都应该优先于单个玩家的击杀数据。小队如果能保持不断线、不掉队、不乱跑，贡献效率远高于临时单挑。越是大型社区目标，越要把“同一时间出现在同一张图上”视为重要战力。"
      },
      {
        "h": "实战结论",
        "p": "Major Orders 的本质是把“个人打图”升级成“社区协同”。你不需要完美理解所有宏观机制，但至少要做到：先确认目标，再选星球；先看敌人，再换配装；先保住推进节奏，再去追求单局效率。"
      }
    ],
