    "coverImage": "https://placehold.co/1200x675/0f172a/ff6b8b?text=Nest+Guide",
    "coverAlt": "巢穴攻略封面",
    "imageNote": "原创重写内容：围绕虫族巢穴、无伤拆除、火力分配与撤离安全进行整理。",
    "sourceNotes": [
      "参考公开攻略中关于虫族巢穴、触发距离、远程爆破和清场节奏的方向。",
      "内容按站内攻略风格重写，保留实战逻辑，不沿用原文句式。"
    ],
    "body": [
      "巢穴在很多人的印象里只是地图上的一个小目标，但真正打过高难的人都知道，它往往是整张图里最容易把队伍拖进连锁战斗的点。巢穴本身通常不会让你瞬间暴毙，真正麻烦的是你一旦靠得太近，周围巡逻、近战虫、飞行单位和后续刷新会一起压上来，把一场本来能速拆的目标变成持续消耗战。",
      "如果想把巢穴打得稳，第一件事不是找火力，而是找距离。你要先弄清楚什么位置会触发、哪里还能安全观察、哪里是撤退线。很多队伍的问题不是火力不足，而是人站得太急、太近、太满，结果还没把目标点拆掉，退路已经被自己走没了。巢穴战说到底不是拼谁先开枪，而是拼谁先把战场摆对。",
      "最稳的处理顺序通常是先看外围，再看本体。也就是说，先扫一眼有没有巡逻队往这边来，先确认有没有远程虫或者会打断节奏的单位，最后再决定是直接爆破，还是先清一轮外围再上手。这样做的核心价值是，你不会在建筑已经被打残的时候才发现，身后还跟着一整队虫群。",
      "单刷时，这个顺序更重要。你没有队友帮你兜底，所以每一次站位都必须给自己留出退路。贴脸拆巢穴虽然看起来快，但一旦补给跟不上，或者刷怪位置和你预期不一样，局面就会直接变成追着跑。相比之下，先拉开角度、先压外围、再集中拆点，通常更稳，也更适合反复练习。",
      "武器和战略配备的选择，应该围绕“拆点能力”和“脱战能力”来定，而不是只看面板伤害。能快速处理固定目标的装备当然重要，但同样重要的是，当第一轮没拆干净时，你还有没有办法稳住场面。高爆武器、反结构支援、范围爆炸投掷物、以及带压制效果的战略配备，通常都比单纯追求高伤害更适合巢穴场景。",
      "如果是组队，建议在开打前就把职责分好。一个人负责看边，盯着有没有巡逻和飞行单位靠近；一个人负责拆点，确保主目标持续掉血；剩下的人负责补刀和清杂，避免虫群在你开火的时候贴脸。四个人都把火力堆在本体上，很多时候并不会更快，反而容易在半路被围住，最后谁都没打完。",
      "巢穴战里最常见的翻车点有三个。第一是接近阶段太冒进，没摸清周围环境就直接往里冲。第二是拆除阶段不看外围，只顾着往核心目标上砸火力，结果被新刷出来的虫子卡住节奏。第三是撤离阶段太放松，目标刚倒就开始松队形，最后反而在离开时被回头的虫群追上。只要你把这三个阶段分开处理，成功率会比“见到就打”高很多。",
      "另一个常见误区，是以为巢穴必须一次打完。实际上，只要压力过大、角度不好、或者资源不够，后撤一步重新组织完全正常。先把外围压力拆开，再回头拆本体，往往比硬扛更稳。很多人所谓的‘无伤’，不是因为他们打得更猛，而是因为他们更少贪刀、更少硬顶、更少把自己送进包围圈。",
      "如果你想把巢穴打得更稳定，进点前最好先确认三件事：路线有没有绕开主要刷怪带，撤离口是不是留得住，支援技能是不是还在冷却中。只要这三件事都清楚，巢穴就只是一个需要按步骤处理的可选目标，而不是会把整局节奏彻底打乱的麻烦点。",
      "最后总结一句：巢穴战拼的不是火力声势，而是战场管理能力。能控制距离、能分清先后顺序、能给自己留退路的队伍，通常都能用更低的代价完成拆除。"
    ],
    "sections": [
      {
        "h": "巢穴为什么危险",
        "p": "巢穴类目标最麻烦的地方，不是建筑本身多硬，而是它很容易把你拖进一整套连锁反应：巡逻队靠近、刷新压力上升、退路被切断、队伍阵型变乱。只要你把它当成一个需要控制战场节奏的目标，而不是单纯一个建筑，处理难度就会明显下降。"
      },
      {
        "h": "先看距离，再决定怎么打",
        "p": "打巢穴之前，最重要的是确认安全线和触发线。能在不触发的情况下完成观察、标记和站位，就先别急着开火。你越是愿意多花几秒确认角度，后面要花的时间就越少。远程拆除和爆破手段，应当优先在敌人贴脸之前使用。"
      },
      {
        "h": "推荐处理顺序",
        "p": "稳妥的顺序一般是：先压外围巡逻，再处理会干扰节奏的小怪和远程单位，最后再集中火力拆本体。这样做不是慢，而是避免把自己放进一个已经失控的战斗环境里。巢穴战翻车，很多时候不是目标没打掉，而是打到一半退不出来。"
      },
      {
        "h": "虫族战区下的推荐配装思路",
        "p": "虫族图里，优先考虑能快速拆固定目标、同时还能兼顾脱战的配置。反坦克武器、爆炸类投掷物、高机动护甲、以及能迅速拉开距离的支援，都比单纯堆伤害更实用。单刷玩家尤其要给自己留补救手段，别把自己锁死在巢穴旁边。"
      },
      {
        "h": "最常见的失误",
        "p": "最常见的失误主要有三种：一是靠得太近，二是没清外围就急着开爆，三是巢穴没完全处理完就提前散队。把这三点控制住，巢穴的难度会下降很多。"
      },
      {
        "h": "实战结论",
        "p": "巢穴攻略不是比谁火力更大，而是比谁更会控制局面。会找距离、会留退路、会分步骤处理目标的队伍，通常都能更稳地完成无伤拆除。"
      }
    ],
